import sys

def main():
    n = int(sys.stdin.readline().strip())
    for i in range(n):
        stars = 2 * i + 1
        if i < n - 1:
            spaces = n - 1 - i
            line = ' ' * spaces + ' '.join(['*'] * stars)
        else:
            line = ' '.join(['*'] * (2 * n - 1))
        print(line)

if __name__ == "__main__":
    main()
